#include <stdio.h>
int main(void)
{
    int from[3]={0,1,2},to[3]={1,2,1},w[3]={4,-3,2};
    int d[3]={999,999,999},edges=3;
    d[0]=0;
    for(int pass=0;pass<2;pass++) {
        for(int e=0;e<edges;e++) {
            int u=from[e],v=to[e];
            if(d[u]!=999 && d[u]+w[e]<d[v]) { d[v]=d[u]+w[e]; }
        }
    }
    int improve=0;
    for(int e=0;e<edges;e++) {
        if(d[from[e]]!=999 && d[from[e]]+w[e]<d[to[e]]) { improve=1; }
    }
    printf("%d\n",improve);
    return 0;
}
